  [412020] = { "Cura nel tempo.", nil, 0xedc7437a, nil, "um" },
  [412096] = { "Mossa risolutiva che squarcia tutti i nemici entro $N1 m, facendoli sanguinare nel tempo. Dura di più e infligge più danni per ogni punto combo.\n\n$N2 punto: $N3 danni in $D1.\n $N5 punti: $N6 danni in $D2.\n $N8 punti: $N9 danni in $D3.\n $N11 punti: $N12 danni in $D4.\n $N14 punti: $N15 danni in $D5.\n\nTempesta Cremisi beneficia di tutti i talenti e gli effetti che si attivano da Perforazione o la modificano.", "$N1 danni da sanguinamento subiti ogni $D1.", 0xa7e6cd0a, 0x84eecd00, "uu" },
  [412113] = { "Rimuove $N1 maledizione e $N2 effetto magico dannoso da un bersaglio amico.", nil, 0x0a40d597, nil, "um" },
  [412115] = { "I tuoi incantesimi ⟦Mana Shield=Scudo di Mana⟧, ⟦Frost Ward=Protezione dal Gelo⟧ e ⟦Fire Ward=Guardia di Fuoco⟧ ora possono essere lanciati su qualsiasi bersaglio amico e assorbono il $N1% di danni in più, e ⟦Mana Shield=Scudo di Mana⟧ consuma il $N2% di mana in meno per ogni danno assorbito. Inoltre, il tuo Remove Lesser Curse è sostituito da Remove Greater Curse.\n\n$I1\nRimuove $N3 maledizione e $N4 effetto magico dannoso da un bersaglio amico.", nil, 0xb762f9d3, nil, "um" },
  [412116] = { "Assorbe $N1 danni fisici su un bersaglio amico, prosciugando mana al loro posto. Prosciuga $N2 mana dal Mago che lancia l'incantesimo per ogni danno assorbito. Dura $D1.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0xff96538f, 0xd9625b22, "uu" },
  [412118] = { "Assorbe $N1 danni fisici su un bersaglio amico, prosciugando mana al loro posto. Prosciuga $N2 mana dal Mago che lancia l'incantesimo per ogni danno assorbito. Dura $D1.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0xff96538f, 0xd9625b22, "uu" },
  [412120] = { "Assorbe $N1 danni fisici su un bersaglio amico, prosciugando mana al loro posto. Prosciuga $N2 mana dal Mago che lancia l'incantesimo per ogni danno assorbito. Dura $D1.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0xff96538f, 0xd9625b22, "uu" },
