  [412286] = { "Aumenta del $N1% la probabilità di critico di tutti i tuoi incantesimi, ma i tuoi critici magici non periodici hanno ora un costo in mana aggiuntivo pari al $N2% del tuo mana base.", nil, 0xabdf0c02, nil, "um" },
  [412322] = { "Aumenta del $N1% il bonus ai danni dei colpi critici di tutti gli incantesimi.", nil, 0xdc154266, nil, "um" },
  [412324] = { "Infliggi il $N1% di danni in più mentre hai più del $N2% di mana. Mentre sei sotto il $N3% di mana, il $N4% della tua rigenerazione del mana continua durante il lancio di incantesimi.", nil, 0x5f43a0b7, nil, "um" },
  [412325] = { "Permette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", nil, 0x86815c0c, nil, "um" },
  [412326] = { "Aumenta del $N1% tutti i danni magici inflitti.", nil, 0x915ea14f, nil, "um" },
  [412428] = { "Macina insieme $N1 Windfury Cone per creare un unguento velenoso per armi. In teoria.", nil, 0x1536ef81, nil, "um" },
  [412437] = { "Scaglia un dardo di gelo contro il nemico, infliggendo $N1 danni da gelo.", nil, 0x2e8656ae, nil, "um" },
  [412507] = { "Squartamento ora può essere usato in Postura da Berserker, i suoi danni aumentano del $N1% e infligge danni aggiuntivi pari al $N2% della tua potenza d'attacco ogni volta che infligge danni.", nil, 0x2d9ea468, nil, "um" },
  [412510] = { "Cura di $N2 salute in $D1 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui e applica Temporal Beacon a ciascun bersaglio per $D2.\n\nTemporal Beacon\n$I1\nRegistra la posizione spazio-temporale del soggetto. Il $N5% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N6% su sé stessi, e ridotta anche del $N7% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", "Cura di $N1 salute in $D1.", 0x6a708596, 0x71292dfd, "uu" },
  [412513] = { "Una postura aggressiva che, mentre indossi uno scudo, aumenta i danni del $N1% e la probabilità di blocco del $N2%, ma riduce l'Armatura del $N3% e la minaccia generata del $N4%. Inoltre, ottieni il $N5% di rabbia in più quando il tuo attacco automatico danneggia un nemico che non ti ha come bersaglio.\n\nMentre indossi uno scudo in Gladiator Stance, puoi usare tutte le abilità riservate alle altre posture.", nil, 0xd9f8b649, nil, "um" },
  [412526] = { "Infligge danni da ombra a un nemico e ne riduce la velocità di movimento per $D1.", nil, 0xb24a12b1, nil, "um" },
  [412532] = { "Scaglia un dardo di geloincanto contro il nemico, infliggendo $N1 danni da geloincanto e rallentandone la velocità di movimento del $N2% per $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e all'arcano del bersaglio, e conta sia come danni da gelo sia come danni da arcano.", "Velocità di movimento ridotta del $N1%.", 0x9762e582, 0xbe1d3d24, "uu" },
  [412538] = { "Infligge danni da fuoco ogni $D1.", nil, 0x9b32ec1a, nil, "um" },
  [412545] = { "Infligge danni da fuoco ogni $D1.", nil, 0x1a8da46b, nil, "um" },
  [412613] = { "Sanguinante.", nil, 0xd6c5aa1b, nil, "um" },
  [412689] = { "Ogni volta che il tuo incantesimo ⟦Drain Life=Risucchio di Vita⟧, Risucchio d'Anima o Dardo d'Ombra infligge danni, la tua Corruzione sul bersaglio viene riportata alla durata massima.", nil, 0xe2052567, nil, "um" },
  [412718] = { "Prova a sfilettare un ⟦Raw Brilliant Smallfish=Pesciolino Brillante⟧.", nil, 0x18bbd6e4, nil, "um" },
  [412727] = { "Aumenta del $N1% la probabilità di critico di tutti gli attacchi tuoi e del tuo demone evocato mentre il demone è attivo.", nil, 0x8615a59f, nil, "um" },
  [412732] = { "Aumenta i danni magici tuoi e del tuo famiglio demoniaco fino al $N1% del tuo livello mentre hai un famiglio demoniaco evocato attivo.", nil, 0xc91f815d, nil, "um" },
  [412751] = { "Aumenta del $N1% la probabilità di critico del tuo incantesimo Conflagrazione.", nil, 0xacdd60b7, nil, "um" },
  [412758] = { "Infligge $N1 danni da fuoco al bersaglio e un ulteriore $N2% di danni se il bersaglio è afflitto da Immolazione.", nil, 0x2c6958c3, nil, "um" },
  [412787] = { "Soffoca il nemico con un'ondata di energia d'ombra che infligge $N1 danni, interrompe il lancio di incantesimi e impedisce di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0xdc558c70, nil, "um" },
  [412788] = { "Carica un nemico e lo stordisce per $D1. Non utilizzabile in combattimento.", nil, 0x6acf62c8, nil, "um" },
  [412789] = { "Costringe tutti i nemici vicini a concentrare i loro attacchi su di te per $D1.", "Provocato.", 0x0cbe2fc8, 0x36f56123, "uu" },
  [412790] = { "Balza in aria e piomba su tutti i nemici entro $N1 m dall'area bersaglio, infliggendo $N2 danni da ombra e stordendoli per $D1.", "Stordito.", 0x2ca8bc76, 0x27f95286, "uu" },
  [412798] = { "Ogni volta che infliggi un colpo critico a un nemico, tu e il tuo famiglio demoniaco ottenete una probabilità di schivata pari al $N1% della tua probabilità di critico magico, e recuperate entrambi il $N2% del mana massimo.", nil, 0x71845730, nil, "um" },
  [412800] = { "Aumenta la probabilità di schivata di un valore pari al $N1% della tua probabilità di critico magico.", nil, 0x331eed36, nil, "um" },
